using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Valora.Application.Access;
using Valora.Application.ActionCenter;
using Valora.Application.Common;
using Valora.Application.Exceptions;
using Valora.Application.Workspace;
namespace Valora.Web.Controllers;

[Authorize(Policy=ValoraPermissions.Action.Read), Route("ActionCenter")]
public sealed class ActionCenterController(ActionPlanService plans,ActionItemService items,ActionProgressService progress,ICurrentRequestContext requestContext) : Controller {
    private CurrentRequestContext Context=>requestContext.GetCurrent();
    private bool Wide=>Context.IsGlobalAdministrator||Context.Roles.Contains("admin_cliente",StringComparer.OrdinalIgnoreCase);
    private bool Manage=>Context.IsGlobalAdministrator||Context.Permissions.Contains(ValoraPermissions.Action.Manage,StringComparer.OrdinalIgnoreCase);
    private bool CompletePermission=>Context.IsGlobalAdministrator||Context.Permissions.Contains(ValoraPermissions.Action.Complete,StringComparer.OrdinalIgnoreCase);
    private bool TryScope(out Guid o,out Guid u){var x=Context;o=x.EffectiveOrganizationId??Guid.Empty;u=x.UserId??Guid.Empty;return o!=Guid.Empty&&u!=Guid.Empty;}
    [HttpGet("")] public async Task<IActionResult> Index(CancellationToken c){if(!TryScope(out var o,out var u))return View("MissingOrganization");return View(await plans.Dashboard(o,u,Wide,c));}
    [HttpGet("Plans")] public async Task<IActionResult> Plans(CancellationToken c){if(!TryScope(out var o,out var u))return View("MissingOrganization");return View(await plans.List(o,u,Wide,c));}
    [HttpGet("Plans/Create"),Authorize(Policy=ValoraPermissions.Action.Manage)] public IActionResult CreatePlan(string? originType,Guid? originId)=>TryScope(out _,out _)?View(new CreateActionPlanRequest("","",originType=="ai_insight"?originType:"manual",originType=="ai_insight"?originId:null,null,null,null,"medium",null,null,null,"","")):View("MissingOrganization");
    [ValidateAntiForgeryToken,HttpPost("Plans/Create"),Authorize(Policy=ValoraPermissions.Action.Manage)] public async Task<IActionResult> CreatePlan(CreateActionPlanRequest r,CancellationToken c){if(!TryScope(out var o,out var u))return Forbid();if(!ModelState.IsValid)return View(r);try{var id=await plans.Create(o,u,r,c);return RedirectToAction(nameof(PlanDetails),new{id});}catch(Exception e)when(e is ArgumentException or ConflictAppException){ModelState.AddModelError("",e.Message);return View(r);}}
    [HttpGet("Plans/Details/{id:guid}")] public async Task<IActionResult> PlanDetails(Guid id,int itemPage=1,CancellationToken c=default){if(!TryScope(out var o,out var u))return Forbid();return await PlanPage(o,u,id,itemPage,null,null,c);}
    [ValidateAntiForgeryToken,HttpPost("Items/Create"),Authorize(Policy=ValoraPermissions.Action.Manage)] public async Task<IActionResult> CreateItem(CreateActionItemRequest r,int itemPage=1,CancellationToken c=default){if(!TryScope(out var o,out var u))return Forbid();if(ModelState.IsValid)try{var id=await items.Create(o,u,r,c);return RedirectToAction(nameof(ItemDetails),new{id});}catch(Exception e)when(e is ArgumentException or ConflictAppException){ModelState.AddModelError("",e.Message);}return await PlanPage(o,u,r.ActionPlanId,itemPage,r,"create-item-dialog",c);}
    [HttpGet("Items")] public async Task<IActionResult> Items(int page=1,string? status=null,CancellationToken c=default){if(!TryScope(out var o,out var u))return View("MissingOrganization");return View(new ActionItemListViewModel(await items.List(o,u,null,Wide,page,20,status,c),status));}
    [HttpGet("Items/Details/{id:guid}")] public async Task<IActionResult> ItemDetails(Guid id,int historyPage=1,CancellationToken c=default){if(!TryScope(out var o,out var u))return Forbid();return await ItemPage(o,u,id,historyPage,null,null,c);}
    [ValidateAntiForgeryToken,HttpPost("Items/{id:guid}/Progress"),Authorize(Policy=ValoraPermissions.Action.Manage)] public Task<IActionResult> Update(Guid id,ProgressActionRequest request,CancellationToken c)=>ExecuteCommand(id,"progress-dialog",request,()=>progress.Update(Context.RequireOrganizationId(),Context.RequireUserId(),id,Wide,request,c),c);
    [ValidateAntiForgeryToken,HttpPost("Items/{id:guid}/Block"),Authorize(Policy=ValoraPermissions.Action.Manage)] public Task<IActionResult> Block(Guid id,TransitionActionRequest request,CancellationToken c)=>ExecuteCommand(id,"block-dialog",request,()=>progress.Block(Context.RequireOrganizationId(),Context.RequireUserId(),id,Wide,request,c),c);
    [ValidateAntiForgeryToken,HttpPost("Items/{id:guid}/Resume"),Authorize(Policy=ValoraPermissions.Action.Manage)] public Task<IActionResult> Resume(Guid id,TransitionActionRequest request,CancellationToken c)=>ExecuteCommand(id,"resume-dialog",request,()=>progress.Resume(Context.RequireOrganizationId(),Context.RequireUserId(),id,Wide,request,c),c);
    [ValidateAntiForgeryToken,HttpPost("Items/{id:guid}/Complete"),Authorize(Policy=ValoraPermissions.Action.Complete)] public Task<IActionResult> Complete(Guid id,CompleteActionRequest request,CancellationToken c)=>ExecuteCommand(id,"complete-dialog",request,()=>progress.Complete(Context.RequireOrganizationId(),Context.RequireUserId(),id,Wide,request,c),c);
    private async Task<IActionResult> ExecuteCommand(Guid id,string dialog,object request,Func<Task> command,CancellationToken c){if(!TryScope(out var o,out var u))return Forbid();if(ModelState.IsValid)try{await command();TempData["ActionSuccess"]="Registro atualizado com sucesso.";return RedirectToAction(nameof(ItemDetails),new{id});}catch(ConcurrencyConflictException e){ModelState.AddModelError("",e.Message+" Consulte os dados atuais antes de reenviar.");}catch(Exception e)when(e is ConflictAppException or ArgumentException){ModelState.AddModelError("",e.Message);}catch(KeyNotFoundException){return NotFound();}return await ItemPage(o,u,id,1,request,dialog,c);}
    private async Task<IActionResult> ItemPage(Guid o,Guid u,Guid id,int page,object? command,string? dialog,CancellationToken c){var detail=await items.Details(o,u,id,Wide,Manage,CompletePermission,page,c);return detail is null?NotFound():View("ItemDetails",new ActionItemPageViewModel(detail,command,dialog));}
    private async Task<IActionResult> PlanPage(Guid o,Guid u,Guid id,int page,CreateActionItemRequest? command,string? dialog,CancellationToken c){var plan=await plans.Get(o,u,id,Wide,c);if(plan is null)return NotFound();var activities=await items.List(o,u,id,Wide,page,10,null,c);return View("PlanDetails",new ActionPlanDetailsViewModel(plan,activities,await items.ResponsibleOptions(o,c),Manage,command,dialog));}
}
[Authorize] public sealed class ActionPlansController:Controller{[HttpGet("ActionPlans")][HttpGet("ValoraAction")]public IActionResult Index()=>Redirect("/ActionCenter/Plans");}
public sealed record ActionPlanDetailsViewModel(ActionPlanDto Plan,PageResult<ActionItemDto> Activities,IReadOnlyList<ActionOptionDto> ResponsibleOptions,bool CanCreate,CreateActionItemRequest? Command,string? OpenDialog);
public sealed record ActionItemPageViewModel(ActionItemDetailsDto Details,object? Command,string? OpenDialog);
public sealed record ActionItemListViewModel(PageResult<ActionItemDto> Page,string? Status);
